OFFICIAL_DIR = os.path.join(HERE, "sim_data", "official")

def load_official(name):
    """Data gathered by collect_data.py (data_training.bat) in sim_data/official/. None if not there."""
    try:
        with open(os.path.join(OFFICIAL_DIR, name), encoding="utf8") as fh:
            return json.load(fh)
    except Exception:
        return None

def _fred_latest(series_id):
    url = f"https://fred.stlouisfed.org/graph/fredgraph.csv?id={series_id}"
    req = urllib.request.Request(url, headers={"User-Agent": "civility-sim/1.0"})
    with urllib.request.urlopen(req, timeout=15) as r:
        rows = r.read().decode().strip().splitlines()[1:]
    for row in reversed(rows):
        parts = row.split(",")
        try:
            return float(parts[1]), parts[0]
        except (ValueError, IndexError):
            continue
    return None, None

def load_data(names, offline=False):
    """Returns {county: dict(pop, burden, commute, lat, lon, src)} using built-in, cached or downloaded ACS data."""
    os.makedirs(os.path.join(HERE, "sim_data"), exist_ok=True)
    cache_path = os.path.join(HERE, "sim_data", "fred_cache.json")
    cache = {}
    if os.path.exists(cache_path):
        try:
            cache = json.load(open(cache_path))
        except Exception:
            cache = {}
    need = []
    for n in names:
        fips = COUNTIES[n][0]
        b, c = BUILTIN_ACS.get(n, (None, None))
        if b is None and f"DP04ACS006{fips}" not in cache:
            need.append(f"DP04ACS006{fips}")
        if c is None and f"B080ACS006{fips}" not in cache:
            need.append(f"B080ACS006{fips}")
        if f"PPAACA06{fips}A156NCEN" not in cache:          # Census SAIPE poverty rate, all ages
            need.append(f"PPAACA06{fips}A156NCEN")
        if f"LAUCN06{fips}0000000003A" not in cache:        # BLS LAUS unemployment rate, annual
            need.append(f"LAUCN06{fips}0000000003A")
        if f"HC01ESTVC1606{fips}" not in cache:             # ACS: % adults 25+ with high school diploma or more
            need.append(f"HC01ESTVC1606{fips}")
    if need and not offline:
        print(f"Downloading {len(need)} Census series from FRED (one time)...")

        def get(sid):
            try:
                return sid, _fred_latest(sid)
            except Exception:
                return sid, (None, None)

        with ThreadPoolExecutor(8) as ex:
            for sid, (val, date) in ex.map(get, need):
                if val is not None:
                    cache[sid] = [val, date]
        json.dump(cache, open(cache_path, "w"), indent=1)
    if not offline and not any(k.startswith("BINGE") for k in cache):
        # CDC PLACES 2025 release: binge drinking among adults, age-adjusted %, every CA county in one request
        try:
            url = ("https://data.cdc.gov/resource/swc5-untb.json?$limit=500&stateabbr=CA"
                   "&measureid=BINGE&datavaluetypeid=AgeAdjPrv")
            req = urllib.request.Request(url, headers={"User-Agent": "civility-sim/1.0"})
            with urllib.request.urlopen(req, timeout=20) as r:
                for row in json.loads(r.read().decode()):
                    loc = str(row.get("locationid", ""))
                    if len(loc) == 5 and loc.startswith("06") and row.get("data_value") not in (None, ""):
                        cache[f"BINGE{loc[2:]}"] = [float(row["data_value"]), str(row.get("year", ""))]
            json.dump(cache, open(cache_path, "w"), indent=1)
            print("Downloaded CDC binge-drinking rates.")
        except Exception as e:
            print(f"Couldn't download CDC binge-drinking rates ({e}); using the state average.")
    out, missing = {}, []
    for n in names:
        fips, pop, lat, lon = COUNTIES[n]
        b, c = BUILTIN_ACS.get(n, (None, None))
        src = "ACS 2020-2024"
        if b is None:
            b = (cache.get(f"DP04ACS006{fips}") or [None])[0]
        if c is None:
            c = (cache.get(f"B080ACS006{fips}") or [None])[0]
        if b is None or c is None:
            missing.append(n)
            src = "partly estimated (download failed)"
            b = b if b is not None else 40.0
            c = c if c is not None else 26.0
        pov = (cache.get(f"PPAACA06{fips}A156NCEN") or [None])[0]
        if pov is None:
            src += "; poverty estimated"
            pov = 13.0
        unemp = (cache.get(f"LAUCN06{fips}0000000003A") or [None])[0]
        hs = (cache.get(f"HC01ESTVC1606{fips}") or [None])[0]
        binge = (cache.get(f"BINGE{fips}") or [None])[0]
        if unemp is None or hs is None or binge is None:
            src += "; some new factors estimated"
        out[n] = dict(pop=pop, burden=b, commute=c, lat=lat, lon=lon, src=src, housinsecu=PLACES_HEALTH[n][3],
                      poverty=pov, density=pop / LAND_SQMI[n],
                      unemp=unemp if unemp is not None else 6.0,
                      nohs=100 - hs if hs is not None else 16.0,
                      binge=binge if binge is not None else 16.0)
    if missing:
        print(f"Warning: couldn't get ACS data for {len(missing)} counties ({', '.join(missing[:6])}"
              f"{'...' if len(missing) > 6 else ''}); using state averages for them. Re-run when online to retry.")
    return out

W_DEFAULT = dict(base=-2.6, w_trait=0.8, w_stress=1.1, w_irr=1.5, w_rent=0.6, commute_div=45.0,
                 w_hard=0.0, hit=0.45, social=0.02, w_pov=0.0, w_dens=0.0,
                 w_unemp=0.0, w_edu=0.0, w_drink=0.0, w_move=0.0,
                 w_pol=0.0, w_drift=0.0, w_civic=0.0, w_ec=0.0, w_vol=0.0,
                 w_alone=0.0, w_wfh=0.0, w_mob=0.0, w_dsoc=0.0, w_alt=0.0,
                 w_strain=0.0, w_trust=0.0, w_sour=0.0)

MEET = dict(mode="classic",
            low_share=0.4,       # share of people who go out little (homebound, remote, isolated)
            p_high=0.55,         # daily chance of an encounter for everyone else
            p_low=0.18,          # ...and for the people who go out little
            strangers=2.0,       # brief encounters with strangers on a day out (cashiers, drivers, crowds)
            witness=1.0,         # people who see each rude act in public, on average
            bystander=0.3)

MOVE_RATE = 0.06

LEVERS = ("burden", "commute", "slack", "grace", "reward", "cons", "exile", "civic", "robots")

START = dict(slack=25, grace=10, reward=10, cons=15, exile=0, civic=0)

CIVIC = dict(deter=0.3, cost=1.0, penalty=50.0, report=0.3, false_rate=0.0005, reward=5.0, reward_rate=0.01,
             recover=1 / 365, grade_stress=dict(B=0.15, C=0.4, D=0.7))

CIVIC_GRADES = (("A", 960), ("B", 850), ("C", 600), ("D", 0))

ROBOTS = dict(visit_below=50.0, visit_rate=1 / 60,
              hold_days=7, arrest_days=3, lethal_p=0.3,
              fine=500.0,       # dollars per citation; paid down about $10 a day
              arrest_points=5.0,  # rating points a record costs
              lockout_act=0.6,  # share of usual daily encounters for someone locked out (under 20)
              lockout_stress=0.25,
              aware=0.35,       # extra restraint for people within reach of a cutoff (they know the rubric)
              fleet=0.0002,     # robot capacity: visits a day per resident of the county (about 2,000 a day in LA County)
              fear=0.12,        # stress for everyone in a county where the robots patrol
              deter=0.25,       # people hold back where the robots patrol
              flee=0.6,         # ...and are more likely to move away
              watch=0.5,        # share of public incidents within view of a patrol robot's cameras where they patrol
              misread=0.0005,   # ordinary moments the cameras log as an incident (a raised voice, a shove in a crowd)
              penalty=8.0,      # record points an incident costs
              recover=0.003)

NEURAL = dict(seed=0.01,             # share of people with a brain-sensing wearable when the trend starts
              growth=0.25, cap=0.6,  # spreads like other gadgets, most people never wear one all day
              share=0.6,             # of wearers, share who let rating apps use their neural data (the rest opt out)
              mouse_years=10,        # whole mouse connectome: around a decade out
              human_hazard=0.06,     # after the mouse: each year a 6% chance the human connectome is finished (~17 yrs)
              # how much EEG cuts misreads, and adds to catching real rudeness, at each stage
              stages={"eeg": (0.25, 0.05), "mouse": (0.4, 0.08), "human": (0.7, 0.15)})

PRIVATE_AI = dict(seed=0.02, growth=0.9, catch=0.5, penalty=8.0, ai_error=0.002, recover=0.003, cost=0.6, deter=0.25,
                  push_adopt=0.25, fair_error_x=0.3, fair_cost_x=0.6,
                  # rating apps also listen through users' phone microphones in public: tone, wording, rude or double-edged phrasing
                  mic_reach=0.6,      # share of public encounters within earshot of a rating-app phone (times local adoption)
                  mic_catch=0.5,      # share of rude encounters that are audible/verbal enough to score
                  mic_misread=0.02,   # ordinary encounters scored as rude (sarcasm, slang, accents, jokes, double meanings)
                  mic_uneven=0.2,     # share of people misread twice as often (the rest a bit less, same average)
                  mic_deter=0.10,     # people guard what they say when phones may be listening
                  mic_stress=0.05)

class Region:
    def __init__(self, data, scale, seed, dev, area_people=250_000, weights=None, min_area_agents=1):
        self.W = dict(W_DEFAULT)
        if weights:
            self.W.update(weights)
        self.names = list(data)
        self.data = data
        self.dev = dev
        K = self.K = len(self.names)
        g = torch.Generator(device=dev)
        g.manual_seed(seed)
        self.g = g
        rnd = lambda *s: torch.rand(*s, generator=g, device=dev)
        nrm = lambda *s: torch.randn(*s, generator=g, device=dev)
        self.rnd = rnd
        self.nrm = nrm
        self.moved = torch.zeros(K, device=dev)

        # neighborhoods: every real census tract when collected (sim_data/official/tracts.json), else generated areas
        tr = load_official("tracts.json")
        a_county, a_size, a_rows = [], [], []
        self.area_src = "generated neighborhoods (~1 per 250,000 people)"
        by_c = {}
        if tr:
            for gid, row in tr["tracts"].items():
                by_c.setdefault(row[0], []).append(row)
        for ci, n in enumerate(self.names):
            pop = data[n]["pop"]
            rows = by_c.get(int(COUNTIES[n][0]))
            if rows:
                # the county's people (DOF total) split across its tracts by each tract's real population
                total = max(min_area_agents, round(pop / scale))
                tp = sum(r[4] for r in rows)
                for r in rows:
                    a_county.append(ci)
                    a_size.append(max(1, round(total * r[4] / tp)))
                    a_rows.append(r)
                continue
            na = max(1, round(pop / area_people))
            per = max(min_area_agents, round(pop / scale / na))
            a_county += [ci] * na
            a_size += [per] * na
            a_rows += [None] * na
        if tr and any(a_rows):
            self.area_src = f"real census tracts ({sum(1 for r in a_rows if r):,}, ACS {tr.get('year', '')})"
        self.A = len(a_size)
        self.a_size = torch.tensor(a_size, device=dev)
        self.a_start = torch.cumsum(self.a_size, 0) - self.a_size
        self.a_county = torch.tensor(a_county, device=dev)
        self.n = n = int(self.a_size.sum())
        self.area = torch.repeat_interleave(torch.arange(self.A, device=dev), self.a_size)
        self.county = self.a_county[self.area]
        c_size = torch.bincount(self.a_county, weights=self.a_size.float(), minlength=K).long()
        self.c_size = c_size
        self.c_start = torch.cumsum(c_size, 0) - c_size
        self.c_bounds = [(int(s), int(s + z)) for s, z in zip(self.c_start.tolist(), c_size.tolist())]
        self.a_boff = nrm(self.A) * 6           # local rent pressure varies around the county figure
        self.a_cm = torch.exp(nrm(self.A) * 0.15)
        self.a_pov = torch.zeros(self.A, device=dev)       # tract poverty vs. its county (stress units)
        self.a_unemp = torch.zeros(self.A, device=dev)
        self.a_dens = None                                 # tract density replaces county density when known
        self.a_ec = self.a_vol = None
        self.a_alone = self.a_wfh = self.a_moved = None
        self.a_wfhf = None                                 # share working from home (0-1), skips their commute
        self.tract_geo = None
        if any(a_rows):
            cty = tr["county"]
            fz = lambda v: v if v is not None else float("nan")
            boff, cmul, pv, un, dens, ec, vol, geo = [], [], [], [], [], [], [], []
            alone, wfh, moved = [], [], []
            for a, r in enumerate(a_rows):
                ci = a_county[a]
                cr = cty.get(str(int(COUNTIES[self.names[ci]][0])), [None] * 5)
                if r is None:
                    boff.append(float(self.a_boff[a])); cmul.append(float(self.a_cm[a])); pv.append(0.0); un.append(0.0)
                    dens.append(float("nan")); ec.append(float("nan")); vol.append(float("nan")); geo.append(None)
                    alone.append(float("nan")); wfh.append(float("nan")); moved.append(float("nan"))
                    continue
                xr = (list(r) + [None, None, None])[11:14]
                alone.append(fz(xr[0])); wfh.append(fz(xr[1])); moved.append(fz(xr[2]))
                boff.append((r[5] - cr[0]) if r[5] is not None and cr[0] is not None else 0.0)
                cmul.append(min(3.0, max(0.3, r[6] / cr[1])) if r[6] and cr[1] else 1.0)
                pv.append(((r[7] - cr[2]) / 5) if r[7] is not None and cr[2] is not None else 0.0)
                un.append(((r[8] - cr[3]) / 2) if r[8] is not None and cr[3] is not None else 0.0)
                dens.append(math.log10(max(1.0, r[4] / max(r[3], 0.01))) - 2.5)
                ec.append(fz(r[9])); vol.append(fz(r[10]))
                geo.append((r[1], r[2], max(0.3, math.sqrt(r[3] * 2.59 / math.pi))))
            self.a_boff = torch.tensor(boff, device=dev).float()
            self.a_cm = torch.tensor(cmul, device=dev).float()
            self.a_pov = torch.tensor(pv, device=dev).float()
            self.a_unemp = torch.tensor(un, device=dev).float()
            def zt(vals):
                v = torch.tensor(vals, dtype=torch.float64)
                ok = ~torch.isnan(v)
                if int(ok.sum()) < 10:
                    return None
                z = (v - v[ok].mean()) / v[ok].std().clamp(min=1e-9)
                return torch.where(ok, z, torch.zeros_like(z)).float().to(dev)
            d = torch.tensor(dens, dtype=torch.float64)
            self.a_dens = torch.where(torch.isnan(d), torch.zeros_like(d), d).float().to(dev)
            self.a_ec, self.a_vol = zt(ec), zt(vol)
            self.a_alone, self.a_wfh, self.a_moved = zt(alone), zt(wfh), zt(moved)
            if self.a_wfh is not None:
                wv = torch.tensor(wfh, dtype=torch.float64)
                self.a_wfhf = torch.where(torch.isnan(wv), torch.zeros_like(wv), wv / 100).clamp(0, 0.9).float().to(dev)
            self.tract_geo = geo

        # cross-county contact: real commuting flows (Census ACS 2016-2020) when collected, else a gravity model
        fipsK = [int(COUNTIES[x][0]) for x in self.names]
        com = load_official("commute.json")
        self.contact_src = "gravity model (modeled)"
        if com and K > 1:
            M = torch.zeros(K, K, dtype=torch.float64)
            res_workers = torch.zeros(K, dtype=torch.float64)
            for i, fi in enumerate(fipsK):
                row = com.get(str(fi), {})
                res_workers[i] = sum(row.values())
                for j, fj in enumerate(fipsK):
                    if i != j:
                        M[i, j] = row.get(str(fj), 0)
        else:
            M = None
        pops = torch.tensor([data[x]["pop"] for x in self.names], dtype=torch.float64)
        lat = torch.tensor([data[x]["lat"] for x in self.names], dtype=torch.float64)
        lon = torch.tensor([data[x]["lon"] for x in self.names], dtype=torch.float64)
        dy = (lat[:, None] - lat[None, :]) * 111
        dx = (lon[:, None] - lon[None, :]) * 111 * torch.cos(torch.deg2rad(lat))[:, None]
        d = torch.sqrt(dx ** 2 + dy ** 2).clamp(min=15)
        pull = pops[None, :] / d ** 2
        pull.fill_diagonal_(0)
        own = pops / 25.0 ** 2
        self.out_share = (0.3 * pull.sum(1) / (pull.sum(1) + own)).clamp(0.02, 0.25).float().to(dev)
        self.G = (pull / pull.sum(1, keepdim=True).clamp(min=1e-12)).float().to(dev) if K > 1 else None
        if M is not None and float(M.sum()) > 0:
            C = M + M.T        # people meet across county lines through work, in both directions
            share = (M.sum(1) + M.sum(0)) / (2 * res_workers.clamp(min=1))
            self.out_share = (0.6 * share).clamp(0.02, 0.3).float().to(dev)
            self.G = (C / C.sum(1, keepdim=True).clamp(min=1e-12)).float().to(dev)
            self.contact_src = "real commuting flows (Census ACS 2016-2020)"
        # cumulative contact table, all counties in one sorted list, so step() picks every partner county in one GPU call
        self.G_flat = None
        if self.G is not None:
            cum = torch.cumsum(self.G.double(), 1)
            cum = cum / cum[:, -1:].clamp(min=1e-12)
            self.G_flat = (cum + torch.arange(K, device=dev, dtype=torch.float64)[:, None]).flatten().contiguous()

        # moving: real county-to-county moves (IRS 2023-24) - how many leave the state vs. move within it, and where to
        irs = load_official("irs_moves.json")
        self.mv_out_state = torch.ones(K, device=dev)      # share of movers who leave the simulated area entirely
        self.mv_dest = None
        self.moves_src = "everyone who moves leaves the state (no data)"
        if irs and K > 1:
            D = torch.zeros(K, K, dtype=torch.float64)
            out_state = torch.ones(K, dtype=torch.float64)
            for i, fi in enumerate(fipsK):
                row = irs["F"].get(str(fi), {})
                st = irs["S"].get(str(fi))
                for j, fj in enumerate(fipsK):
                    if i != j:
                        D[i, j] = row.get(str(fj), 0)
                total = (st[1] + st[2] + st[3]) if st else 0
                if total > 0:
                    out_state[i] = 1 - min(1.0, float(D[i].sum()) / total)
            self.mv_out_state = out_state.float().to(dev)
            rs = D.sum(1, keepdim=True)
            self.mv_dest = torch.where(rs > 0, D / rs.clamp(min=1e-12), torch.full_like(D, 1.0 / K)).float().to(dev)
            self.moves_src = "real county-to-county moves (IRS 2023-24)"
        self.moved_in = torch.zeros(K, device=dev)

        # social media: moods spread along real friendship ties (Meta Social Connectedness Index) when collected
        sci = load_official("sci.json")
        self.sci_w = None
        self.feed_src = "one statewide feed (modeled)"
        if sci and K > 1:
            Wsci = torch.zeros(K, K, dtype=torch.float64)
            for i, fi in enumerate(fipsK):
                row = sci.get(str(fi), {})
                for j, fj in enumerate(fipsK):
                    Wsci[i, j] = row.get(str(fj), 0.0) * pops[j]       # friends there = connectedness x people there
            if float(Wsci.sum()) > 0:
                self.sci_w = (Wsci / Wsci.sum(1, keepdim=True).clamp(min=1e-12)).float().to(dev)
                self.feed_src = "real friendship ties (Meta Social Connectedness Index)"
        # social capital (Social Capital Atlas): standardized across counties, 0 where missing
        cap = load_official("social_capital.json") or {}
        def zcol(key):
            v = torch.tensor([float(cap.get(str(fi), {}).get(key, float("nan"))) for fi in fipsK], dtype=torch.float64)
            ok = ~torch.isnan(v)
            if int(ok.sum()) < 3:
                return torch.zeros(K, device=dev)
            z = (v - v[ok].mean()) / v[ok].std().clamp(min=1e-9)
            return torch.where(ok, z, torch.zeros_like(z)).float().to(dev)
        self.z_ec, self.z_vol = zcol("ec"), zcol("volunteering_rate")

        # levers per county
        self.L = {k: torch.zeros(K, device=dev) for k in LEVERS}
        self.L["burden"] = torch.tensor([data[x]["burden"] for x in self.names], device=dev).float()
        self.L["commute"] = torch.tensor([data[x]["commute"] for x in self.names], device=dev).float()
        self.hard = (torch.tensor([data[x].get("housinsecu", 15.0) for x in self.names], device=dev).float() - 15) / 10
        self.pov = (torch.tensor([data[x].get("poverty", 13.0) for x in self.names], device=dev).float() - 13) / 5
        self.unemp = (torch.tensor([data[x].get("unemp", 6.0) for x in self.names], device=dev).float() - 6) / 2
        self.nohs = (torch.tensor([data[x].get("nohs", 16.0) for x in self.names], device=dev).float() - 16) / 6
        self.drink = (torch.tensor([data[x].get("binge", 16.0) for x in self.names], device=dev).float() - 16) / 3
        # places to get together (County Business Patterns): bars, and everything else (cafes, gyms, congregations,
        # clubs, theaters) per resident, as z-scores across counties. Drinking does two things in the model:
        #   w_drink (>= 0): heavy drinking raises the odds of snapping at someone
        #   w_dsoc:  drinking is also how many people socialize - it can ease disconnection, more so where bars are
        #            the main place to meet and less so where there are other places (w_alt) to go
        self.z_bars = self.z_alt = None
        tp = load_official("third_places.json")
        if tp and tp.get("counties"):
            def per(kinds):
                v = torch.tensor([sum(tp["counties"].get(str(int(COUNTIES[x][0])), {}).get(k, 0) for k in kinds)
                                  / max(1, data[x]["pop"]) * 1e4 for x in self.names], dtype=torch.float64)
                v = torch.log1p(v)
                return ((v - v.mean()) / v.std().clamp(min=1e-9)).float().to(dev)
            self.z_bars = per(["bars"])
            self.z_alt = per([k for k in tp.get("kinds", {}) if k != "bars"] or ["cafes", "fitness", "religious", "civic", "arts"])
        self.dens = torch.log10(torch.tensor([max(1.0, data[x].get("density", 300.0)) for x in self.names], device=dev).float()) - 2.5
        for k, v in START.items():
            self.L[k] += v
        self.outrage = 0.7
        self.acc = 0.95

        # people
        self.idx = torch.arange(n, device=dev)
        self.trait = nrm(n)
        self.cm = torch.exp(0.45 * nrm(n) - 0.1)
        self.ur = rnd(n) * 100
        self.ug = rnd(n) * 100
        self.online = rnd(n) ** 1.5
        self.irr = torch.zeros(n, device=dev)
        self.shock = torch.zeros(n, device=dev)
        self.norm = torch.zeros(n, device=dev)
        self.alive = torch.ones(n, dtype=torch.bool, device=dev)
        self.hostile = self.trait > 2.054
        # politics: each person's fictional leaning, drawn at the county's real registration mix
        E_ = [ELECTIONS.get(x, dict(r16=0.4, r20=0.4, r24=0.4, dem=0.45, rep=0.25, ind=0.2, vote=0.6)) for x in self.names]
        tens = lambda key: torch.tensor([e[key] for e in E_], device=dev).float()
        self.e_dem, self.e_rep, self.e_ind = tens("dem"), tens("rep"), tens("ind")
        self.e_r24 = tens("r24")
        self.e_trend = tens("r24") - (tens("r16") + tens("r20")) / 2      # + = Republicans gained since 2016-20
        self.e_novote = 1 - tens("vote")
        self.party = self._draw_party(self.county)     # 0 Democrat, 1 Republican, 2 independent/other, 3 not registered
        self._setup_polls()
        self.me = None                                 
        self.me_mask = None
        self.cv = dict(CIVIC)
        self.civic = torch.full((n,), 1000.0, device=dev)   # everyone starts equal; only matters where the program runs
        self.cv_reports = torch.zeros(K, device=dev)
        self.cv_false = torch.zeros(K, device=dev)
        self.ai = dict(PRIVATE_AI)
        self.rep = torch.full((n,), 80.0, device=dev)       # patrol robots' camera record (0-100); matters where robots patrol
        self.adopt = torch.zeros(K, device=dev)              # share of landlords/employers/apps in the county using ratings
        self.ai_reports = torch.zeros(K, device=dev)
        self.ai_mistakes = torch.zeros(K, device=dev)
        self.removed = torch.zeros(K, device=dev)
        self.wrong = torch.zeros(K, device=dev)
        self.log = []   # per day: (kind_c, rude_c, stress_c, heat_c, state_heat)
        self.vi = None  # indices of the statewide sample shown in the 3D view (see build_people)
        self.tracks = {}  # name -> dict(idx, kind, rude, stress, irr): people whose daily actions we report

    def robot_visits(self, c, rnd):
        n, K, RB = self.n, self.K, ROBOTS
        if getattr(self, "rb_count", None) is None or self.rb_count.shape[0] != 7:
            # warned, detained, fined, arrested, killed, wrongly visited, wrongly killed
            self.rb_count = torch.zeros(7, K, device=self.dev)
            self.rb_total = torch.zeros(7, K, device=self.dev)
        if getattr(self, "rb_lethal", None) is None:
            self.rb_lethal = torch.ones(K, device=self.dev)        # a court can bar the lethal tier
        if getattr(self, "fines", None) is None:
            self.fines = torch.zeros(n, device=self.dev)           # unpaid fines, dollars
            self.strikes = torch.zeros(n, dtype=torch.int16, device=self.dev)   # under-20 visits so far
        on = self.L["robots"][c] > 0.5
        r = self.rep
        cand = on & self.alive & (r < RB["visit_below"]) & (self.held == 0)
        n_c = torch.bincount(c[cand], minlength=K).float()
        cap = torch.tensor([self.data[x]["pop"] for x in self.names], device=self.dev).float() * RB["fleet"] / getattr(self, "scale", 1)
        rate = torch.minimum(torch.full_like(n_c, RB["visit_rate"]), cap / n_c.clamp(min=1))   # a fleet can only be so many places
        visit = cand & (rnd(n) < rate[c])
        if not bool(visit.any()):
            return
        warn = visit & (r >= 35)
        hold = visit & (r < 35) & (r >= 20)
        low = visit & (r < 20)
        kill = low & (r < 10) & (self.rb_lethal[c] > 0.5) & (rnd(n) < RB["lethal_p"])
        arrest = low & ~kill & ((self.strikes > 0) | (r < 10))      # repeat visit (or under 10): booked
        fine = low & ~kill & ~arrest                                  # first visit under 20: a citation
        self.strikes = torch.where(low, self.strikes + 1, self.strikes)
        wrongly = visit & (r + self.rep_wrong >= RB["visit_below"])   # wouldn't be under 50 without the AI's mistakes
        self.held = torch.where(hold, torch.full_like(self.held, RB["hold_days"]), self.held)
        self.held = torch.where(arrest, torch.full_like(self.held, RB["arrest_days"]), self.held)
        self.fines = self.fines + RB["fine"] * (fine | arrest).float()
        self.rep = torch.where(arrest, (self.rep - RB["arrest_points"]).clamp(min=0), self.rep)
        self.shock += 0.4 * warn.float() + 0.8 * hold.float() + 0.5 * fine.float() + 1.0 * arrest.float()
        self.alive &= ~kill
        if getattr(self, "rb_last", None) is None:
            self.rb_last = torch.zeros(n, dtype=torch.uint8, device=self.dev)   # last visit, for the 3D view
        for code, t in ((1, warn), (2, hold), (3, fine), (4, arrest), (5, kill)):
            self.rb_last = torch.where(t, torch.full_like(self.rb_last, code), self.rb_last)
        for i, t in enumerate((warn, hold, fine, arrest, kill, wrongly, kill & wrongly)):
            b = torch.bincount(c[t], minlength=K).float()
            self.rb_count[i] += b
            self.rb_total[i] += b

    def civic_stats(self, cis):
        """Grades, average and reports for a group of counties (the pilot or the comparison counties)."""
        sel = torch.zeros(self.n, dtype=torch.bool, device=self.dev)
        for ci in cis:
            s0, e0 = self.c_bounds[ci]
            sel[s0:e0] = True
        sel &= self.alive
        v = self.civic[sel]
        g, prev = {}, None
        for name, lo in CIVIC_GRADES:
            m = v >= lo if prev is None else (v >= lo) & (v < prev)
            g[name] = float(m.float().mean()) if v.numel() else 0.0
            prev = lo
        rep_ = float(self.cv_reports[cis].sum()) if cis else 0.0
        fal = float(self.cv_false[cis].sum()) if cis else 0.0
        return dict(avg=float(v.mean()) if v.numel() else 1000.0, grades=g, reports=int(rep_), mistaken=int(fal))

    def _setup_polls(self):
        """Attitudes from real poll respondents (polls.json). Centered on the statewide average, so 0 = a typical Californian."""
        self.p_strain = self.p_distrust = self.p_sour = None
        self.polls_src = "no poll data (run build_polls.py)"
        pj = load_official("polls.json")
        if not pj or not pj.get("pools"):
            return
        keys = sorted(pj["pools"])
        flat, start, size = [], [], []
        for k in keys:
            start.append(len(flat)); size.append(len(pj["pools"][k])); flat += pj["pools"][k]
        P = torch.tensor(flat, dtype=torch.float32, device=self.dev)         # rows: distrust, sour, strain, weight
        st = pj.get("statewide", {})
        self._poll_vals = P[:, :3] - torch.tensor([st.get("distrust", 0.5), st.get("sour", 0.5), st.get("strain", 0.5)], device=self.dev)
        # cumulative weights inside each pool, laid end to end, so one searchsorted call draws for everyone
        w = P[:, 3].double()
        cum = torch.zeros_like(w)
        for s0, z in zip(start, size):
            c_ = torch.cumsum(w[s0:s0 + z], 0)
            cum[s0:s0 + z] = c_ / c_[-1] + len([1 for x in start if x < s0])   # pool i spans (i, i+1]
        self._poll_cum = cum.contiguous()
        self._poll_start = torch.tensor(start, device=self.dev)
        self._poll_size = torch.tensor(size, device=self.dev)
        idx = {k: i for i, k in enumerate(keys)}
        cp = pj.get("county_pool", {})
        self._poll_of_county = torch.tensor([idx.get(cp.get(COUNTIES[x][0], ""), idx.get("Other", 0)) for x in self.names], device=self.dev)
        self.p_distrust = torch.zeros(self.n, device=self.dev)
        self.p_sour = torch.zeros(self.n, device=self.dev)
        self.p_strain = torch.zeros(self.n, device=self.dev)
        self._draw_polls(self.idx if hasattr(self, "idx") else torch.arange(self.n, device=self.dev), self.county)
        self.polls_src = (f"real poll respondents ({pj.get('counts', {}).get('respondents', 0):,}, {pj.get('source', 'PPIC')}); "
                          f"{sum(1 for k in keys if k in COUNTIES)} counties with their own pool")

    def _draw_polls(self, ix, cty):
        """Give people ix (living in counties cty) a real respondent's answers from their county's pool."""
        if self.p_strain is None or ix.numel() == 0:
            return
        pool = self._poll_of_county[cty]
        u = pool.double() + self.rnd(ix.numel()).double().clamp(1e-9, 1 - 1e-9)
        j = torch.searchsorted(self._poll_cum, u).clamp(max=self._poll_cum.numel() - 1)
        j = torch.minimum(torch.maximum(j, self._poll_start[pool]), self._poll_start[pool] + self._poll_size[pool] - 1)
        v = self._poll_vals[j]
        self.p_distrust[ix], self.p_sour[ix], self.p_strain[ix] = v[:, 0], v[:, 1], v[:, 2]

    def _draw_party(self, cty):
        u = self.rnd(cty.numel())
        d, r, i = self.e_dem[cty], self.e_rep[cty], self.e_ind[cty]
        return torch.where(u < d, 0, torch.where(u < d + r, 1, torch.where(u < d + r + i, 2, 3)))

    def detachment(self, c):
        """Per person: how politically out of place they are (0..1, 0.5 = neutral) and how much their side slipped."""
        dem, rep_ = self.party == 0, self.party == 1
        r = self.e_r24[c]
        mismatch = torch.where(dem, r, torch.where(rep_, 1 - r, torch.full_like(r, 0.5)))   # share of the other side
        slip = torch.where(dem, self.e_trend[c], torch.where(rep_, -self.e_trend[c], torch.zeros_like(r)))
        return mismatch, slip

    def shock_county(self, ci, frac, amt):
        s, e = self.c_bounds[ci]
        self.shock[s:e] += (self.rnd(e - s) < frac).float() * amt

    def step(self):
        n, K, rnd, L, W = self.n, self.K, self.rnd, self.L, self.W
        c = self.county
        self.irr *= 0.96
        self.shock *= 0.97
        self.norm *= 0.995
        slack = L["slack"][c] / 100
        self.shock += (rnd(n) < 0.003).float() * 1.6 * (1 - 0.7 * slack)
        burden = (L["burden"][c] + self.a_boff[self.area]).clamp(0, 95)
        severe = self.ur < burden * 0.6
        lvl = severe.float() * 2 + ((~severe) & (self.ur < burden)).float()
        on_c = (L["civic"] > 0.5)
        has_civic = False     # the Civic Score program was taken out of the simulation (Nov 2026)
        on = on_c[c].float() if has_civic else None
        commute = L["commute"][c] * self.cm * self.a_cm[self.area] * getattr(self, "holiday_cm", 1.0)
        if "w_wfh" in W and getattr(self, "a_wfhf", None) is not None:   # (worlds saved before this data keep their old commute)
            commute = commute * (1 - self.a_wfhf[self.area])
        ar = self.area
        stress = ((lvl * W["w_rent"] + (commute - 30) / W["commute_div"] + 0.5 + W["w_hard"] * self.hard[c]
                   + W["w_pov"] * (self.pov[c] + self.a_pov[ar])
                   + W["w_unemp"] * (self.unemp[c] + self.a_unemp[ar])
                   + (W.get("w_strain", 0.0) * self.p_strain if getattr(self, "p_strain", None) is not None else 0.0)) * (1 - 0.6 * slack)
                  + self.shock).clamp(min=0)
        has_ai = False        # behavior-rating apps were taken out of the simulation (Nov 2026)
        aig = lambda k: self.ai.get(k, PRIVATE_AI[k])     # saved worlds from before the microphone feature lack these keys
        if has_ai:      # a low private rating means friction (apartments, gigs, jobs), as often as ratings are used
            low = ((80.0 - self.rep) / 40.0).clamp(0, 1)
            stress = stress + self.adopt[c] * self.ai["cost"] * low * 0.6
            stress = stress + self.adopt[c] * aig("mic_reach") * aig("mic_stress")
        if has_civic:   # lower civic grades cost something real (lost perks, fees, eligibility)
            gs = self.cv["grade_stress"]
            pen = torch.where(self.civic >= 960, 0.0, torch.where(self.civic >= 850, gs["B"], torch.where(self.civic >= 600, gs["C"], gs["D"])))
            stress = stress + on * self.cv["cost"] * pen
        if "robots" not in L:            # worlds saved before the robots existed
            L["robots"] = torch.zeros(K, device=self.dev)
        rb_any = bool((L["robots"] > 0.5).any())
        rbc = L["robots"][c] if rb_any else 0.0
        if rb_any:
            stress = stress + ROBOTS["fear"] * rbc
            if getattr(self, "fines", None) is not None:          # unpaid robot fines weigh on people
                stress = stress + 0.15 * (self.fines / ROBOTS["fine"]).clamp(max=3)
            stress = stress + ROBOTS["lockout_stress"] * rbc * (self.rep < 20).float()
        grace = self.ug < L["grace"][c]
        p = torch.sigmoid(W["base"] + W["w_trait"] * self.trait + W["w_stress"] * stress + W["w_irr"] * self.irr
                          + W["w_dens"] * (self.a_dens[ar] if self.a_dens is not None else self.dens[c])
                          + W["w_edu"] * self.nohs[c] + W["w_drink"] * self.drink[c] - self.norm - 1.2 * grace.float()
                          + (W.get("w_trust", 0.0) * self.p_distrust if getattr(self, "p_distrust", None) is not None else 0.0)
                          - W.get("w_ec", 0.0) * (self.a_ec[ar] if self.a_ec is not None else self.z_ec[c])
                          - W.get("w_vol", 0.0) * (self.a_vol[ar] if self.a_vol is not None else self.z_vol[c])
                          - (self.cv["deter"] * on if has_civic else 0.0)
                          - ROBOTS["deter"] * rbc
                          - (ROBOTS["aware"] * rbc * ((self.rep < 60) & (self.rep >= 10)).float() if rb_any else 0.0)
                          - ((self.ai["deter"] + aig("mic_deter") * aig("mic_reach")) * self.adopt[c] if has_ai else 0.0))

        # moving away: the more stressed, the likelier to leave; a newcomer takes their place
        mismatch, slip = self.detachment(c)
        pull = (W.get("w_mob", 0.0) * (self.a_moved[self.area] if getattr(self, "a_moved", None) is not None else 0.0)
                + ROBOTS["flee"] * rbc
                + W.get("w_move", 0.0) * (stress - 1.0) + W.get("w_pol", 0.0) * (mismatch - 0.5) * 2
                + W.get("w_drift", 0.0) * slip * 10 + W.get("w_civic", 0.0) * (self.e_novote[c] - 0.4) * 3
                + (W.get("w_sour", 0.0) * self.p_sour * 2 if getattr(self, "p_sour", None) is not None else 0.0))
        q_leave = (MOVE_RATE / 365.0) * torch.exp(pull.clamp(min=-3.0, max=3.0))
        leave = (rnd(n) < q_leave) & self.alive
        if self.me_mask is not None:
            leave &= ~self.me_mask                     
        if bool(leave.any()):
            ix = torch.nonzero(leave).flatten()
            m = ix.numel()
            self.moved += torch.bincount(c[ix], minlength=K).float()
            # some movers stay in California: they take their personality to a home in another county
            if self.mv_dest is not None:
                stay = rnd(m) >= self.mv_out_state[c[ix]]
                if bool(stay.any()):
                    mv = ix[stay]
                    dest = torch.multinomial(self.mv_dest[c[mv]], 1, replacement=True, generator=self.g).flatten()
                    slot = torch.minimum(self.c_start[dest] + (rnd(mv.numel()) * self.c_size[dest]).long(), self.c_start[dest] + self.c_size[dest] - 1)
                    ok = self.alive[slot] & ~leave[slot]
                    if self.me_mask is not None:
                        ok &= ~self.me_mask[slot]
                    mv, slot, dest = mv[ok], slot[ok], dest[ok]
                    self.trait[slot] = self.trait[mv]
                    self.cm[slot] = self.cm[mv]
                    self.online[slot] = self.online[mv]
                    self.party[slot] = self.party[mv]
                    if getattr(self, "p_strain", None) is not None:   # their attitudes move with them
                        self.p_distrust[slot], self.p_sour[slot], self.p_strain[slot] = self.p_distrust[mv], self.p_sour[mv], self.p_strain[mv]
                    self.hostile[slot] = self.hostile[mv]
                    self.ur[slot] = rnd(slot.numel()) * 100      # a new home: their housing situation is redrawn there
                    self.ug[slot] = self.ug[mv]
                    self.irr[slot] = self.irr[mv] * 0.5          # a fresh start takes the edge off
                    self.shock[slot] = 0
                    self.norm[slot] = 0
                    self.civic[slot] = self.civic[mv]
                    self.rep[slot] = self.rep[mv]
                    self.moved_in += torch.bincount(dest, minlength=K).float()
            self.trait[ix] = self.nrm(m)
            self.cm[ix] = torch.exp(0.45 * self.nrm(m) - 0.1)
            self.ur[ix] = rnd(m) * 100
            self.ug[ix] = rnd(m) * 100
            self.online[ix] = rnd(m) ** 1.5
            self.irr[ix] = 0
            self.shock[ix] = 0
            self.norm[ix] = 0
            self.hostile[ix] = self.trait[ix] > 2.054
            self.party[ix] = self._draw_party(c[ix])
            if getattr(self, "p_strain", None) is not None:
                self._draw_polls(ix, c[ix])                # newcomers: a fresh respondent from the county's pool
            self.civic[ix] = 1000.0
            self.rep[ix] = 80.0
            if getattr(self, "held", None) is not None:
                self.held[ix] = 0
                self.rep_wrong[ix] = 0.0
            if getattr(self, "fines", None) is not None:
                self.fines[ix] = 0.0
                self.strikes[ix] = 0
        self.q_leave_c = torch.bincount(c, weights=q_leave * self.alive.float(), minlength=K) / torch.bincount(c, weights=self.alive.float(), minlength=K).clamp(min=1)

        social = MEET["mode"] == "social"
        if social:
            if getattr(self, "sociab", None) is None or self.sociab.numel() != n:
                self.sociab = torch.where(rnd(n) < MEET["low_share"], MEET["p_low"], MEET["p_high"])
            act = (rnd(n) < self.sociab) & self.alive
        else:
            act = (rnd(n) < 0.3) & self.alive
        if getattr(self, "held", None) is not None:
            act &= self.held == 0          # detained: out of circulation
            self.held = (self.held - 1).clamp(min=0)
        if "robots" in self.L and bool((self.L["robots"] > 0.5).any()):   # locked out of transit, buildings, apps
            lock = (self.L["robots"][c] > 0.5) & (self.rep < 20)
            act &= ~lock | (rnd(n) < ROBOTS["lockout_act"])
        if getattr(self, "fines", None) is not None:
            self.fines = (self.fines - 10.0).clamp(min=0)
        a_s, a_z = self.a_start[self.area], self.a_size[self.area]
        local = torch.minimum(a_s + (rnd(n) * a_z).long(), a_s + a_z - 1)
        c_s, c_z = self.c_start[c], self.c_size[c]
        same = torch.minimum(c_s + (rnd(n) * c_z).long(), c_s + c_z - 1)
        partner = torch.where(rnd(n) < 0.8, local, same)
        if self.G is not None:
            u = rnd(n)
            go = u < self.out_share[c]
            Kc = self.G.shape[0]
            v = c.double() + rnd(n).double().clamp(max=1 - 1e-9)
            tgt = (torch.searchsorted(self.G_flat, v, right=True) - c * Kc).clamp(0, Kc - 1)
            t_s, t_z = self.c_start[tgt], self.c_size[tgt]
            other = torch.minimum(t_s + (rnd(n) * t_z).long(), t_s + t_z - 1)
            partner = torch.where(go, other, partner)
        act &= (partner != self.idx) & self.alive[partner]
        if social:      # you mostly run into people who are out a lot themselves
            act &= rnd(n) < (self.sociab[partner] / MEET["p_high"]).clamp(max=1.0)
        rude = act & (rnd(n) < p)
        kind = act & ~rude
        if self.me is not None:
            i = self.me["idx"]
            self.me["month"][0] += float(kind[i]); self.me["month"][1] += float(rude[i])
            self.me["month"][2] += float(stress[i]); self.me["month"][3] += 1
        for tr in self.tracks.values():   # people shown in the 3D view
            ti = tr["idx"]
            tr["kind"] += kind[ti].float()
            tr["rude"] += rude[ti].float()
            tr["stress"] = stress[ti]
            tr["irr"] = self.irr[ti]

        hit = torch.where(grace[partner], 0.06, W["hit"]) * rude.float()
        self.irr.index_add_(0, partner, hit)
        self.irr.index_add_(0, partner, -0.05 * kind.float())
        extra = wit = None
        if social:
            # a day out also brings brief encounters with strangers nearby; some of them are rude
            na = self.a_size.numel()
            pa = torch.bincount(self.area, weights=p * self.alive.float(), minlength=na) / torch.bincount(self.area, weights=self.alive.float(), minlength=na).clamp(min=1)
            m = torch.poisson(torch.full((n,), MEET["strangers"], device=self.dev), generator=self.g) * act.float()
            extra = torch.binomial(m, pa[self.area], generator=self.g)
            self.irr += torch.where(grace, 0.06, W["hit"]) * extra
            # bystanders: people nearby see each rude act and it gets under their skin too
            r_ix = torch.nonzero(rude).flatten()
            if r_ix.numel():
                k = torch.poisson(torch.full((r_ix.numel(),), MEET["witness"], device=self.dev), generator=self.g).long().clamp(max=4)
                src = torch.repeat_interleave(r_ix, k)
                if src.numel():
                    a_s2, a_z2 = self.a_start[self.area[src]], self.a_size[self.area[src]]
                    wit = torch.minimum(a_s2 + (rnd(src.numel()) * a_z2).long(), a_s2 + a_z2 - 1)
                    self.irr.index_add_(0, wit, torch.full((src.numel(),), MEET["bystander"] * W["hit"], device=self.dev))
        self.irr.clamp_(0, 3)
        if getattr(self, "record_day", False):     # realism_check.py: who met whom today and how it went
            self.last_day = (act, rude, partner, extra, wit)

        seen = rude & (rnd(n) < 0.15)
        punished = seen & (rnd(n) < L["cons"][c] / 100)
        self.norm = torch.where(punished, (self.norm + 0.6).clamp(max=2.5), self.norm)
        rewarded = kind & (rnd(n) < L["reward"][c] / 100 * 0.3)
        self.norm = torch.where(rewarded, (self.norm + 0.3).clamp(max=2.5), self.norm)
        self.shock = torch.where(rewarded, self.shock * 0.6, self.shock)
        if has_civic:
            onb = on > 0.5
            reported = seen & onb & (rnd(n) < self.cv["report"])
            mistaken = kind & onb & (rnd(n) < self.cv["false_rate"])
            flag = reported | mistaken
            earned = kind & onb & ~flag & (rnd(n) < self.cv["reward_rate"])
            self.civic = torch.where(flag, (self.civic - self.cv["penalty"]).clamp(min=0), self.civic)
            self.civic = torch.where(earned, (self.civic + self.cv["reward"]).clamp(max=1050), self.civic)
            self.cv_reports += torch.bincount(c[flag], minlength=K).float()
            self.cv_false += torch.bincount(c[mistaken & ~reported], minlength=K).float()
        self.civic += (1000.0 - self.civic).clamp(min=0) * self.cv["recover"]   # lost points heal slowly
        if has_ai:
            ad = self.adopt[c]
            caught = seen & (rnd(n) < ad * self.ai["catch"])
            wrong = kind & (rnd(n) < ad * self.ai["ai_error"] * (1 - self.eeg[c] * NEURAL["share"] * NEURAL["stages"][getattr(self, "neuro_stage", "eeg")][0]
                                                              if getattr(self, "eeg", None) is not None else 1.0))
            mic = ad * aig("mic_reach")          # phones within earshot: no human witness needed
            caught |= rude & (rnd(n) < mic * aig("mic_catch"))
            nm = None
            if getattr(self, "eeg", None) is not None:   # brain-sensing wearables: fewer misreads, a few more real catches
                cut, boost = NEURAL["stages"][getattr(self, "neuro_stage", "eeg")]
                nm = self.eeg[c] * NEURAL["share"]                   # chance this person's neural data reaches the apps
                caught |= rude & (rnd(n) < ad * nm * boost)
            if getattr(self, "mic_x", None) is None:   # how easily each person's speech is misread (fixed per person)
                u = aig("mic_uneven")
                self.mic_x = torch.where(rnd(n) < u, 2.0, (1 - 2.0 * u) / (1 - u))
            wrong |= kind & (rnd(n) < mic * aig("mic_misread") * self.mic_x * (1 - nm * cut if nm is not None else 1.0))
            hitp = caught | wrong
            self.rep = torch.where(hitp, (self.rep - self.ai["penalty"]).clamp(min=0), self.rep)
            self.ai_reports += torch.bincount(c[hitp], minlength=K).float()
            self.ai_mistakes += torch.bincount(c[wrong & ~caught], minlength=K).float()
            if getattr(self, "rep_wrong", None) is None:
                self.rep_wrong = torch.zeros(n, device=self.dev)      # rating points lost to AI mistakes
                self.held = torch.zeros(n, dtype=torch.int16, device=self.dev)
            self.rep_wrong = torch.where(wrong & ~caught, self.rep_wrong + self.ai["penalty"], self.rep_wrong)
            self.rep += (80.0 - self.rep).clamp(min=0) * self.ai["recover"]
            self.rep_wrong *= 1 - self.ai["recover"]
        if rb_any:   # patrol robots log what their own cameras catch; their record is what the rubric acts on
            onr = (L["robots"][c] > 0.5).float()
            if getattr(self, "rep_wrong", None) is None or getattr(self, "held", None) is None:
                self.rep_wrong = torch.zeros(n, device=self.dev)      # record points lost to camera misreads
                self.held = torch.zeros(n, dtype=torch.int16, device=self.dev)
            caught = seen & (rnd(n) < onr * ROBOTS["watch"])       # incidents in public, in view of a patrol
            wrong = kind & ~caught & (rnd(n) < onr * ROBOTS["misread"])
            hitp = caught | wrong
            self.rep = torch.where(hitp, (self.rep - ROBOTS["penalty"]).clamp(min=0), self.rep)
            self.rep_wrong = torch.where(wrong, self.rep_wrong + ROBOTS["penalty"], self.rep_wrong)
            self.rep += (80.0 - self.rep).clamp(min=0) * ROBOTS["recover"]
            self.rep_wrong *= 1 - ROBOTS["recover"]
            self.robot_visits(c, rnd)
        if bool((L["exile"] > 0.5).any()):
            r = rnd(n)
            flagged = seen & (L["exile"][c] > 0.5) & torch.where(self.hostile, r < self.acc, r > self.acc)
            self.alive &= ~flagged
            self.removed += torch.bincount(c[flagged], minlength=K).float()
            self.wrong += torch.bincount(c[flagged & ~self.hostile], minlength=K).float()

        # social media: posts by county, a statewide feed mixed with local feeds
        pr = torch.bincount(c[rude & (rnd(n) < self.online * 0.2)], minlength=K).float()
        pk = torch.bincount(c[kind & (rnd(n) < self.online * 0.05)], minlength=K).float()
        rr, kk = pr * (1 + 3 * self.outrage), pk * (2 - self.outrage)
        local_heat = rr / (rr + kk + 1)
        state_heat = rr.sum() / (rr.sum() + kk.sum() + 1)
        if self.sci_w is not None:   # your feed is mostly your friends, and they live where they live
            heat = 0.5 * local_heat + 0.5 * (self.sci_w @ local_heat)
        else:
            heat = 0.5 * local_heat + 0.5 * state_heat
        self.irr += self.online * W["social"] * heat[c]
        iso = None
        if getattr(self, "a_alone", None) is not None and (W.get("w_alone", 0.0) or W.get("w_wfh", 0.0)):
            iso = W.get("w_alone", 0.0) * self.a_alone[self.area]
            if self.a_wfh is not None:
                iso = iso + W.get("w_wfh", 0.0) * self.a_wfh[self.area]
        if getattr(self, "z_bars", None) is not None and (W.get("w_dsoc", 0.0) or W.get("w_alt", 0.0)):
            # drinking as socializing: counts for more where bars are a big share of the places to meet
            reliance = torch.sigmoid(self.z_bars - self.z_alt)
            soc = W.get("w_dsoc", 0.0) * self.drink * reliance * 2 + W.get("w_alt", 0.0) * self.z_alt
            iso = (iso if iso is not None else 0.0) - soc[c]
        if iso is not None:
            self.irr.add_(0.01 * iso).clamp_(0, 3)

        alive_f = self.alive.float()
        self.log.append(torch.stack([
            torch.bincount(c[kind], minlength=K).float(),
            torch.bincount(c[rude], minlength=K).float(),
            torch.bincount(c, weights=stress * alive_f, minlength=K) / torch.bincount(c, weights=alive_f, minlength=K).clamp(min=1),
            heat,
            state_heat.expand(K),
            torch.bincount(c, weights=self.irr * alive_f, minlength=K) / torch.bincount(c, weights=alive_f, minlength=K).clamp(min=1),
            self.q_leave_c * 365000.0]))   # expected moves away per 1,000 people per year

    def take_log(self):
        if not self.log:
            return None
        x = torch.stack(self.log).cpu()   # days x 6 x K (kind, rude, stress, heat, state heat, irritation)
        self.log = []
        return x

RANGES = dict(base=(-3.6, -1.6), w_trait=(0.3, 1.6), w_stress=(0.2, 2.2), w_irr=(0.1, 2.6), w_rent=(0.1, 1.6),
              commute_div=(20.0, 300.0), w_hard=(0.0, 2.5), hit=(0.1, 0.9), social=(0.0, 0.06),
              w_pov=(0.0, 2.5), w_dens=(-1.0, 1.5),
              w_unemp=(0.0, 2.0), w_edu=(-1.0, 1.5), w_drink=(-1.5, 1.5),
              w_move=(0.0, 3.0), w_pol=(-2.0, 3.0), w_drift=(-2.0, 3.0), w_civic=(-1.0, 3.0),
              w_ec=(-1.5, 1.5), w_vol=(-1.5, 1.5),
              w_alone=(-1.0, 2.0), w_wfh=(-1.0, 2.0), w_mob=(-1.0, 2.0),
              w_dsoc=(-1.0, 2.0), w_alt=(-1.0, 2.0),
              w_strain=(-1.0, 2.5), w_trust=(-1.0, 2.0), w_sour=(-1.0, 2.0))

KEYS = list(RANGES)

BURN, MEASURE = 150, 120

def run_once(theta, seed, data, scale, dev, min_agents):
    sim = Region(data, scale, seed, dev, weights=theta, min_area_agents=min_agents)
    for _ in range(BURN):
        sim.step()
    sim.take_log()
    for _ in range(MEASURE):
        sim.step()
    x = sim.take_log()                    # days x 6 x K
    kind, rude, stress, irr, leave = x[:, 0].sum(0), x[:, 1].sum(0), x[:, 2].mean(0), x[:, 5].mean(0), x[:, 6].mean(0)
    share = rude / (kind + rude).clamp(min=1)
    out = {"log_rude": {}, "stress": {}, "irr": {}, "rude": {}, "leave": {}}
    for i, n in enumerate(sim.names):
        out["rude"][n] = float(share[i])
        out["log_rude"][n] = math.log(max(float(share[i]), 1e-4))
        out["stress"][n] = float(stress[i])
        out["irr"][n] = float(irr[i])
        out["leave"][n] = round(float(leave[i]), 2)   # rounded: when stress plays no part every county is exactly equal
    out["civ"] = float(kind.sum() / (kind.sum() + rude.sum()).clamp(min=1))
    del sim
    if dev.type == "cuda":
        torch.cuda.empty_cache()
    return out

